package com.mhtextractor.core;

import com.mhtextractor.i18n.I18n;
import com.mhtextractor.model.ExtractWarning;
import com.mhtextractor.util.EncodingUtils;
import com.mhtextractor.util.HtmlUtils;
import lombok.Getter;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * 内容提取协调器
 * 基于 MimeParser 解析结果，提取文本和章节标题
 */
@Getter
public class ContentExtractor {
    private static final Logger logger = LoggerFactory.getLogger(ContentExtractor.class);

    private final List<ExtractWarning> lastWarnings = new ArrayList<>();

    /**
     * 从HTML内容中提取纯文本
     */
    public String extractText(String htmlContent, boolean autoFixEncoding,
                              String startMarker, String endMarker, boolean useRegex) {
        lastWarnings.clear();
        if (htmlContent == null || htmlContent.isEmpty()) return null;

        // 检测编码并修复（仅在MimeParser未正确解码时生效）
        if (!EncodingUtils.containsGarbled(htmlContent)) {
            String detectedCharset = EncodingUtils.detectCharsetFromHtml(htmlContent);
            if (detectedCharset != null) {
                try {
                    byte[] htmlBytes = htmlContent.getBytes(StandardCharsets.ISO_8859_1);
                    String reDecoded = new String(htmlBytes, detectedCharset);
                    if (!EncodingUtils.containsGarbled(reDecoded) && EncodingUtils.containsChinese(reDecoded)) {
                        htmlContent = reDecoded;
                        logger.info(I18n.msg("log.contentextractor.01", detectedCharset));
                    }
                } catch (Exception e) {
                    logger.warn(I18n.msg("log.contentextractor.02", e.getMessage()), e);
                }
            }
        }

        // 内容区域限定
        if (startMarker != null && !startMarker.trim().isEmpty()
                && endMarker != null && !endMarker.trim().isEmpty()) {
            htmlContent = extractByMarker(htmlContent, startMarker.trim(), endMarker.trim(), useRegex);
        }

        // HTML → 纯文本
        Document doc = Jsoup.parse(htmlContent);
        doc.body();
        String text = doc.body().wholeText();

        // 乱码修复
        if (autoFixEncoding) {
            text = EncodingUtils.smartFix(text);
        }
        return text;
    }

    /**
     * 从HTML源码中提取章节标题
     */
    public String extractChapterTitle(String htmlContent,
                                      String startMarker, String endMarker, boolean useRegex) {
        lastWarnings.clear();
        if (htmlContent == null || htmlContent.isEmpty()) return null;

        String patternStr = useRegex
                ? startMarker + "(.*?)" + endMarker
                : Pattern.quote(startMarker) + "(.*?)" + Pattern.quote(endMarker);

        try {
            Pattern pattern = Pattern.compile(patternStr, Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
            Matcher matcher = pattern.matcher(htmlContent);
            if (matcher.find()) {
                String title = matcher.group(1).trim()
                        .replaceAll("<[^>]*>", "")
                        .replaceAll("\\s+", " ");
                return title.isEmpty() ? null : title;
            }
        } catch (Exception e) {
            logger.warn(I18n.msg("log.contentextractor.03", e.getMessage()), e);
        }
        return null;
    }

    /**
     * 根据起始/结束标记截取HTML内容
     */
    private String extractByMarker(String html, String startMarker, String endMarker, boolean useRegex) {
        try {
            if (useRegex) {
                Pattern pattern = Pattern.compile(
                        startMarker + "(.*?)" + endMarker,
                        Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
                Matcher matcher = pattern.matcher(html);
                if (matcher.find()) {
                    return matcher.group(1);
                } else {
                    ExtractWarning warning = new ExtractWarning("core.areaMarkersNotFound",
                            Map.of("start", startMarker, "end", endMarker));
                    logger.warn(I18n.msg("log.contentextractor.04", I18n.render(warning)));
                    lastWarnings.add(warning);
                }
            } else {
                String result = HtmlUtils.extractRegion(html, startMarker, endMarker, lastWarnings);
                if (result != null) {
                    return result;
                }
                return html;
            }
        } catch (Exception e) {
            ExtractWarning warning = new ExtractWarning("core.areaExtractFailed",
                    Map.of("reason", String.valueOf(e.getMessage())));
            logger.warn(I18n.render(warning), e);
            lastWarnings.add(warning);
        }
        return html;
    }
}
package com.mhtextractor.processor;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.core.ChapterGenerator;
import com.mhtextractor.core.MimeParser;
import com.mhtextractor.core.SourceParsers;
import com.mhtextractor.extractor.TextExtractor;
import com.mhtextractor.i18n.I18n;
import com.mhtextractor.model.ExtractWarning;
import com.mhtextractor.output.FileWriter;
import com.mhtextractor.model.ExtractOutcome;
import com.mhtextractor.util.SanitizeUtils;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * 文本批量处理器
 * 负责将多个 MHT 文件批量提取文本并写入 TXT（合并或单独模式）
 */
@Slf4j
public class TextBatchProcessor extends BatchProcessor {

    private final AppConfig config;

    public TextBatchProcessor(AppConfig config) {
        this.config = config;
    }

    /**
     * 合并模式（按传入顺序处理，支持每文件覆盖项）
     */
    public ProcessStats processMerged(List<MhtFileInfo> orderedFiles, String outputTxtPath,
                                      ProgressCallback callback, Map<String, PerFileOverrides> overrides) {
        this.progressCallback = callback;
        ProcessStats stats = initStats(I18n.get("extract.mergedMode"), config.getInputFolder());
        log.info(I18n.msg("log.textbatchprocessor.01", outputTxtPath));
        logConfigInfo();
        log.info("========================================");

        if (!FileWriter.createOrClearFile(outputTxtPath)) {
            stats.setEndTime(System.currentTimeMillis());
            return stats;
        }

        return processFiles(orderedFiles, stats, (_, _) -> outputTxtPath, overrides);
    }

    /**
     * 单独模式（按传入顺序处理，支持每文件覆盖项）
     */
    public ProcessStats processSeparate(List<MhtFileInfo> orderedFiles, String outputFolder,
                                        ProgressCallback callback, Map<String, PerFileOverrides> overrides) {
        this.progressCallback = callback;
        ProcessStats stats = initStats(I18n.get("extract.separateMode"), config.getInputFolder());
        log.info(I18n.msg("log.textbatchprocessor.02", outputFolder));
        logConfigInfo();
        log.info("========================================");

        File outDir = new File(outputFolder);
        if (!outDir.exists() || !outDir.isDirectory()) {
            log.error(I18n.msg("log.textbatchprocessor.03", outputFolder));
            stats.setEndTime(System.currentTimeMillis());
            return stats;
        }

        // 条目独立参数需求拍板：单独输出文件名——**用户编辑值优先**（该文件有标题覆盖时用覆盖值，
        // sanitize 后非空即采用）；否则启用标题提取且提取到标题时用标题（sanitize），再否则用原始 mht 文件名
        return processFiles(orderedFiles, stats, (i, parsed) -> {
            String base = getOutputDirName(i.getName());
            // 用户编辑值优先：只要该文件的覆盖标题 sanitize 后非空，就直接用它命名
            PerFileOverrides ov = overrides.getOrDefault(i.getPath(), PerFileOverrides.DEFAULTS);
            String overrideTitle = ov.titleOverride() == null
                    ? "" : SanitizeUtils.sanitize(ov.titleOverride().trim());
            if (!overrideTitle.isEmpty()) {
                base = overrideTitle;
            } else if (config.isEnableTitleExtraction() && parsed != null && parsed.getHtmlContent() != null
                    && config.getTitleStartMarker() != null && !config.getTitleStartMarker().isEmpty()) {
                try {
                    String title = new TextExtractor(parsed).extractTitle(
                            config.getTitleStartMarker(), config.getTitleEndMarker(), config.isTitleUseRegex());
                    if (title != null && !title.trim().isEmpty()) {
                        String s = SanitizeUtils.sanitize(title.trim());
                        if (!s.isEmpty()) {
                            base = s;
                        }
                    }
                } catch (Exception e) {
                    log.debug(I18n.msg("log.textbatchprocessor.04", e.getMessage()), e);
                }
            }
            return Paths.get(outputFolder, base + ".txt").toString();
        }, overrides);
    }

    /**
     * 核心处理循环（合并与单独模式的共用逻辑）
     *
     * @param outputPathResolver 根据 MhtFileInfo 与解析结果计算输出路径
     * @param overrides 每文件覆盖项（按文件路径索引）
     */
    private ProcessStats processFiles(List<MhtFileInfo> mhtFiles, ProcessStats stats,
                                      java.util.function.BiFunction<MhtFileInfo, MimeParser.ParsedMht, String> outputPathResolver,
                                      Map<String, PerFileOverrides> overrides) {
        stats.setTotalFiles(mhtFiles.size());

        if (mhtFiles.isEmpty()) {
            log.warn(I18n.msg("log.textbatchprocessor.05"));
            stats.setEndTime(System.currentTimeMillis());
            return stats;
        }

        log.info(I18n.msg("log.textbatchprocessor.06", mhtFiles.size()));
        log.info("========================================");

        AtomicInteger chapterIndex = new AtomicInteger(1);

        for (int i = 0; i < mhtFiles.size(); i++) {
            MhtFileInfo fileInfo = mhtFiles.get(i);
            if (isCancelled()) {
                log.info(I18n.msg("log.textbatchprocessor.07", i, mhtFiles.size()));
                break;
            }
            try {
                log.info(I18n.msg("log.textbatchprocessor.08", fileInfo.getName()));
                final int idx = i + 1;
                final String name = fileInfo.getName();
                fireProgress(idx, mhtFiles.size(), name, 0.05);
                MimeParser.ParsedMht parsed = SourceParsers.forPath(fileInfo.getPath())
                        .parse(fileInfo.getPath(), recursionContinueCallback,
                        stage -> fireParsingProgress(idx, mhtFiles.size(), name, stage),
                        progress -> fireProgress(idx, mhtFiles.size(), name, progress));
                if (parsed.getHtmlContent() == null) {
                    stats.incrementSkip();
                    stats.addSkipDetail(I18n.get("extract.fileSkippedUnparseable", "file", fileInfo.getName()));
                    recordFileResult(stats, fileInfo.getPath(), ExtractOutcome.SKIPPED,
                            "extract.reasonUnparseable", List.of());
                    log.info(I18n.msg("log.textbatchprocessor.09", fileInfo.getName()));
                    fireProgress(idx, mhtFiles.size(), fileInfo.getName(), 1.0);
                    continue;
                }

                // 提取文本
                fireProgress(idx, mhtFiles.size(), fileInfo.getName(), 0.4);
                TextExtractor textExtractor = new TextExtractor(parsed);
                String text = textExtractor.extractText(config.isAutoFixEncoding(),
                        config.getStartMarker(), config.getEndMarker(), config.isUseRegex());
                List<ExtractWarning> fileWarnings = new ArrayList<>(textExtractor.getLastWarnings());
                reportExtractorWarnings(fileInfo.getName(), textExtractor, stats);

                if (text == null || text.trim().isEmpty()) {
                    stats.incrementSkip();
                    stats.addSkipDetail(I18n.get("extract.fileSkippedEmpty", "file", fileInfo.getName()));
                    recordFileResult(stats, fileInfo.getPath(), ExtractOutcome.SKIPPED,
                            "extract.reasonEmpty", fileWarnings);
                    log.info(I18n.msg("log.textbatchprocessor.10", fileInfo.getName()));
                    fireProgress(idx, mhtFiles.size(), fileInfo.getName(), 1.0);
                    continue;
                }

                // 生成章节头（预览窗口可逐文件关闭；关闭的文件不输出章节头且不占序号）
                fireProgress(idx, mhtFiles.size(), fileInfo.getName(), 0.7);
                boolean addNumber = config.isAddChapterNumber();
                PerFileOverrides ov = overrides.getOrDefault(fileInfo.getPath(), PerFileOverrides.DEFAULTS);
                boolean withChapter = !addNumber || ov.chapterEnabled();
                String chapterHeader = withChapter
                        ? buildChapterHeaderFromParsed(parsed, fileInfo.getName(), chapterIndex.get(), stats,
                                fileWarnings, ov)
                        : null;

                if (addNumber && withChapter) {
                    chapterIndex.incrementAndGet();
                }

                // 写入文件
                fireProgress(idx, mhtFiles.size(), fileInfo.getName(), 0.9);
                String outputPath = outputPathResolver.apply(fileInfo, parsed);
                String startTemplate = config.isEnableTemplate() ? config.getStartTemplate() : "";
                String endTemplate = config.isEnableTemplate() ? config.getEndTemplate() : "";
                boolean ok = FileWriter.appendTextToFile(
                        outputPath, text, fileInfo.getName(), fileInfo.getModifiedTime(),
                        startTemplate, endTemplate, chapterHeader);

                if (ok) {
                    stats.incrementSuccess();
                    recordFileResult(stats, fileInfo.getPath(), ExtractOutcome.SUCCESS, null, fileWarnings);
                } else {
                    stats.incrementFail();
                    stats.addFailDetail(I18n.get("extract.fileFailedWrite", "file", fileInfo.getName()));
                    recordFileResult(stats, fileInfo.getPath(), ExtractOutcome.FAILED,
                            "extract.reasonWriteFailed", fileWarnings);
                }

            } catch (Exception e) {
                stats.incrementFail();
                stats.addFailDetail(I18n.get("extract.fileFailed", "file", fileInfo.getName(),
                        "reason", e.getMessage()));
                recordFileFailure(stats, fileInfo.getPath(), e);
                log.error(I18n.msg("log.textbatchprocessor.11", fileInfo.getName()), e);
            } finally {
                fireProgress(i + 1, mhtFiles.size(), fileInfo.getName(), 1.0);
            }
        }

        stats.setEndTime(System.currentTimeMillis());
        log.info("{}", stats);
        return stats;
    }

    private ProcessStats initStats(String mode, String inputFolder) {
        ProcessStats stats = new ProcessStats();
        stats.setStartTime(System.currentTimeMillis());
        log.info("========================================");
        log.info(I18n.msg("log.textbatchprocessor.12", mode));
        log.info(I18n.msg("log.textbatchprocessor.13", inputFolder));
        return stats;
    }

    private String buildChapterHeaderFromParsed(MimeParser.ParsedMht parsed, String fileName,
                                                int chapterIndex, ProcessStats stats,
                                                List<ExtractWarning> fileWarnings,
                                                PerFileOverrides ov) {
        String extractedTitle = null;
        boolean enableTitleExtract = config.isEnableTitleExtraction();
        String titleStart = config.getTitleStartMarker();
        String titleEnd = config.getTitleEndMarker();

        if (ov != null && ov.hasTitleOverride()) {
            // 用户编辑值优先：跳过标题提取，直接采用用户编辑的标题（仍输出同一条 log.textbatchprocessor.14）
            extractedTitle = ov.titleOverride().trim();
            log.info(I18n.msg("log.textbatchprocessor.14", fileName, extractedTitle));
        } else if (enableTitleExtract && titleStart != null && !titleStart.isEmpty() && parsed.getHtmlContent() != null) {
            try {
                TextExtractor extractor = new TextExtractor(parsed);
                extractedTitle = extractor.extractTitle(titleStart, titleEnd, config.isTitleUseRegex());
                if (extractedTitle != null && !extractedTitle.isEmpty()) {
                    log.info(I18n.msg("log.textbatchprocessor.14", fileName, extractedTitle));
                } else {
                    log.warn(I18n.msg("log.textbatchprocessor.15", fileName, titleStart, titleEnd));
                    stats.incrementWarn();
                    var detailParams = new java.util.HashMap<String, String>();
                    detailParams.put("file", fileName);
                    detailParams.put("start", titleStart);
                    // The old get(..., "end", null) leaves {end} visible in the summary.
                    if (titleEnd != null) detailParams.put("end", titleEnd);
                    stats.addWarnDetail(new com.mhtextractor.model.ExtractionStats.WarningDetail("extract.fileWarnedNoTitle",
                            detailParams, null));
                    fileWarnings.add(new ExtractWarning("extract.noTitleMarkers",
                            Map.of("start", titleStart, "end", String.valueOf(titleEnd))));
                    extractedTitle = null;
                }
            } catch (Exception e) {
                log.debug(I18n.msg("log.textbatchprocessor.16", e.getMessage()), e);
            }
        }

        if (config.isAddChapterNumber()) {
            String numberPart = ChapterGenerator.generateChapterName(chapterIndex - 1);
            if (extractedTitle != null && !extractedTitle.isEmpty()) {
                return numberPart + " " + extractedTitle;
            }
            return numberPart;
        } else if (extractedTitle != null && !extractedTitle.isEmpty()) {
            return extractedTitle;
        }

        return null;
    }

    private void logConfigInfo() {
        if (config.isAddChapterNumber()) {
            log.info(I18n.msg("log.textbatchprocessor.17"));
        }
        if (config.isEnableTitleExtraction()) {
            log.info(I18n.msg("log.textbatchprocessor.18"));
            log.info(I18n.msg("log.textbatchprocessor.19", config.getTitleStartMarker()));
            log.info(I18n.msg("log.textbatchprocessor.20", config.getTitleEndMarker()));
        }
    }

}
package com.mhtextractor.output;

import com.mhtextractor.i18n.I18n;
import com.mhtextractor.util.FileUtils;
import com.mhtextractor.util.SourceKinds;
import lombok.extern.slf4j.Slf4j;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

/**
 * 文本写入工具类
 * 支持模板变量替换、章节名、UTF-8 编码写入
 */
@Slf4j
public class FileWriter {

    private static final DateTimeFormatter DATETIME_FORMATTER =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    /**
     * 将文本内容追加写入文件（支持自定义模板 + 章节名）
     */
    public static boolean appendTextToFile(String outputPath, String text,
                                           String sourceFileName, LocalDateTime fileTime,
                                           String startTemplate, String endTemplate,
                                           String chapterName) {
        if (text == null || text.trim().isEmpty()) {
            log.info(I18n.msg("log.filewriter.01", sourceFileName));
            return false;
        }

        if (startTemplate == null) startTemplate = "";
        if (endTemplate == null) endTemplate = "";

        try (BufferedWriter writer = new BufferedWriter(
                new OutputStreamWriter(new FileOutputStream(outputPath, true), StandardCharsets.UTF_8))) {

            if (chapterName != null && !chapterName.trim().isEmpty()) {
                writer.write(chapterName);
                writer.write("\n\n");
            }

            String startContent = processTemplate(startTemplate, sourceFileName, fileTime);
            writer.write(startContent);
            writer.write(text);
            String endContent = processTemplate(endTemplate, sourceFileName, fileTime);
            writer.write(endContent);

            log.info(I18n.msg("log.filewriter.02", sourceFileName, chapterName != null ? " (" + chapterName + ")" : ""));
            return true;

        } catch (IOException e) {
            log.error(I18n.msg("log.filewriter.03", sourceFileName), e);
            return false;
        }
    }

    /**
     * 创建或清空输出文件（委托给 FileUtils）
     */
    public static boolean createOrClearFile(String outputPath) {
        boolean ok = FileUtils.createOrClearFile(outputPath);
        if (ok) {
            log.info(I18n.msg("log.filewriter.04", outputPath));
        }
        return ok;
    }

    /**
     * 处理模板中的变量替换（预览窗口渲染与正式输出共用）
     */
    public static String processTemplate(String template, String filename, LocalDateTime fileTime) {
        if (template == null || template.isEmpty()) return "";

        String result = template;
        result = result.replace("{basename}", filename != null ? SourceKinds.stripKnownExtension(filename) : "");
        result = result.replace("{filename}", filename != null ? filename : "");

        if (fileTime != null) {
            result = result.replace("{datetime}", fileTime.format(DATETIME_FORMATTER));
            result = result.replace("{date}", fileTime.format(DateTimeFormatter.ofPattern("yyyy-MM-dd")));
            result = result.replace("{time}", fileTime.format(DateTimeFormatter.ofPattern("HH:mm:ss")));
        } else {
            result = result.replace("{datetime}", "");
            result = result.replace("{date}", "");
            result = result.replace("{time}", "");
        }

        result = result.replace("\\n", "\n");
        return result;
    }
}

package com.mhtextractor.baseline;

import com.mhtextractor.i18n.I18n;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Layer A：产物黄金基线（会话 18 · E0.3）。**重构每一步都必须全绿。**
 *
 * <p><b>它证明什么、不证明什么</b>：基线只证明"没变"，不证明"对"。因此必须建立在
 * <b>已验收的正确版本</b>上（本项目已通过 C1–C11 + I1–I10 验收）。已知缺陷会被固化 ——
 * 每例的 {@code knownIssues} 字段显式记录（会话 17 测试方法设计 §3.6）。</p>
 *
 * <p><b>为什么走无头路径而非 GUI</b>：走 {@code TextBatchProcessor} / {@code ImageBatchProcessor}
 * 入口，与 GUI 提取链<b>同源</b>（GUI 的 {@code processUnit} 调用同一入口），但不依赖 JavaFX 运行时。
 * 现有 30 项 GUI 断言只验<b>控件状态</b>，本测试补的是<b>落盘产物内容</b>。</p>
 *
 * <p><b>三层保障</b>：</p>
 * <ol>
 *   <li><b>确定性自检</b>：每例跑两遍（独立工作目录），两遍摘要必须逐字节一致 ——
 *       否则基线本身是噪声，后续每一步都会假失败（风险 R4）。</li>
 *   <li><b>基线比对</b>：与 {@code src/test/resources/baselines/<case>.<loc>.json} 比对。</li>
 *   <li><b>双 locale</b>：zh_CN 与 en_US 各一套（章名/默认输出名随 locale 变化，需求 §3.5 I5）。</li>
 * </ol>
 *
 * <p><b>生成/更新基线</b>：{@code mvn test -Dtest=ProductBaselineTest -Dmht.baseline.capture=true}。
 * <b>更新基线等于声明行为变更</b>，必须显式记录（硬规则 R4）。</p>
 */
class ProductBaselineTest {

    private static final Path BASELINE_DIR = Path.of("src", "test", "resources", "baselines");

    @TempDir
    Path tmp;

    @Test
    void allProductBaselinesMatch() throws Exception {
        boolean capture = BaselineCases.captureRequested();
        List<BaselineCases.Case> cases = BaselineCases.all();
        String onlyCase = System.getProperty("mht.baseline.case");
        if (onlyCase != null) cases = cases.stream().filter(c -> c.name().equals(onlyCase)).toList();
        assertTrue(!cases.isEmpty(), "filter selected no baselines");

        Locale originalLocale = I18n.currentLocale();
        List<String> failures = new ArrayList<>();
        int passed = 0;

        try {
            for (BaselineCases.Case c : cases) {
                for (String loc : List.of("zh", "en")) {
                    I18n.setLocale(loc.equals("zh") ? Locale.SIMPLIFIED_CHINESE : Locale.US);

                    // 确定性自检：同例同 locale 跑两遍（独立目录），摘要必须完全一致
                    BaselineCases.RunResult a = BaselineCases.run(c, tmp.resolve(c.name() + "-" + loc + "-a"));
                    BaselineCases.RunResult b = BaselineCases.run(c, tmp.resolve(c.name() + "-" + loc + "-b"));
                    if (!a.allEquals(b)) {
                        failures.add("[" + c.name() + "/" + loc + "] 确定性自检失败：同输入两遍摘要不一致"
                                + "\n  A.products=" + a.products()
                                + "\n  B.products=" + b.products()
                                + "\n  A.stats=" + a.stats()
                                + "\n  B.stats=" + b.stats());
                        continue;
                    }

                    Path baselineFile = BASELINE_DIR.resolve(c.name() + "." + loc + ".json");
                    String actualJson = BaselineCases.toJson(c, loc, a);

                    if (capture) {
                        Files.createDirectories(BASELINE_DIR);
                        Files.writeString(baselineFile, actualJson, StandardCharsets.UTF_8);
                        passed++;
                    } else {
                        assertTrue(Files.exists(baselineFile), "基线文件缺失：" + baselineFile
                                + "（首次建立请用 -Dmht.baseline.capture=true 重跑）");
                        String expectedJson = Files.readString(baselineFile, StandardCharsets.UTF_8);
                        if (!BaselineCases.normalizeJson(expectedJson)
                                .equals(BaselineCases.normalizeJson(actualJson))) {
                            failures.add("[" + c.name() + "/" + loc + "] 产物基线不一致"
                                    + "\n--- 期望 ---\n" + expectedJson + "\n--- 实际 ---\n" + actualJson);
                        } else {
                            passed++;
                        }
                    }
                }
            }
        } finally {
            I18n.setLocale(originalLocale);
        }

        if (capture) {
            System.out.println("[baseline] 重新捕获 " + passed + " 份基线（等于声明行为变更，须显式记录）");
            return;
        }

        System.out.println("[baseline] 通过 " + passed + " 份（zh+en × " + cases.size() + " 例 × 2 遍确定性自检）");
        assertEquals(0, failures.size(),
